// Generated by codelabgen: turn recording placeholders into asciinema players.
document$.subscribe(() => {
  document.querySelectorAll("div.asciinema-cast:not([data-ready])").forEach((el) => {
    el.dataset.ready = "1";
    AsciinemaPlayer.create(el.dataset.src, el, {
      fit: "width",
      idleTimeLimit: 1,
      poster: "npt:0:1",
      theme: "monokai",
    });
  });
});
